package org.sleepwell.app;
import android.service.notification.ZenPolicy;import org.junit.Test;import static org.junit.Assert.*;
/** Real private SharedPreferences, pure injected expiry/rule operations, no policy permission. */
public final class TrackingDndStorageTest {
 @Test public void journalReopensAndOldExpiryCannotRemoveReplacement()throws Exception{try(TrackingDndFixture f=new TrackingDndFixture()){TrackingDndSettings s=f.store();s.enabled(true);TrackingDndOwner owner=new TrackingDndOwner(s,f.port,()->"first");owner.start("run1",true,1000,1,()->true);TrackingDndLease old=s.read();assertTrue(new TrackingDndSettings(f.settings.open(f.c)).read().active);TrackingDndOwner next=new TrackingDndOwner(s,f.port,()->"second");next.start("run2",true,2000,1,()->true);TrackingDndLease current=s.read();next.expire(old.token,old.deadline,old.deadline,1);assertEquals(current.token,s.read().token);assertEquals(2,f.port.on);next.stop("run2");assertNull(s.read());assertTrue(f.port.expiry.isEmpty());}}
 @Test public void failedCleanupKeepsDurableOwnerUntilExplicitRetry()throws Exception{try(TrackingDndFixture f=new TrackingDndFixture()){TrackingDndRuntime.Job j=f.job();j.submit(()->j.owner.start("run",true,1000,1,()->true),true);f.idle();TrackingDndLease original=j.settings.read();f.port.failOff=true;j.cleanup();f.idle();assertNotNull(j.settings.read());assertEquals(original.token,j.settings.read().token);assertTrue(j.state.error.contains("Fixture rule removal failed"));assertFalse(j.settings.enabled());j.preference(true);f.idle();assertTrue("Saving enabled cannot hide failed cleanup",j.state.error.contains("Fixture rule removal failed"));assertEquals(original.token,j.settings.read().token);f.port.failOff=false;j.cleanup();f.idle();assertNull(j.settings.read());assertEquals("",j.state.error);assertTrue(f.port.rules.isEmpty());}}
 @Test public void malformedOwnerIsReportedWithoutActivatingOrClearingEvidence()throws Exception{try(TrackingDndFixture f=new TrackingDndFixture()){assertTrue(f.settings.open(f.c).edit().putString("token","broken").commit());TrackingDndRuntime.Job j=f.job();j.inspect();f.idle();assertTrue(j.state.error.contains("unreadable"));assertEquals("broken",f.settings.open(f.c).getString("token",""));assertEquals(0,f.port.on);}}
 @Test public void rulePolicyObjectPreservesAlarmsCallsMediaAndSystemWithoutOsMutation(){ZenPolicy p=TrackingDndAndroid.policy();assertEquals(ZenPolicy.STATE_ALLOW,p.getPriorityCategoryAlarms());assertEquals(ZenPolicy.STATE_ALLOW,p.getPriorityCategoryMedia());assertEquals(ZenPolicy.STATE_ALLOW,p.getPriorityCategorySystem());assertEquals(ZenPolicy.PEOPLE_TYPE_ANYONE,p.getPriorityCallSenders());assertEquals(ZenPolicy.STATE_ALLOW,p.getPriorityCategoryRepeatCallers());assertEquals(ZenPolicy.PEOPLE_TYPE_NONE,p.getPriorityMessageSenders());assertEquals(ZenPolicy.STATE_DISALLOW,p.getPriorityCategoryEvents());}
}
